from pathlib import Path
import re

APP=Path('src/App.jsx')
app=APP.read_text(encoding='utf-8')

def rep(s,old,new,label):
    if old not in s:
        raise RuntimeError('missing anchor: '+label)
    return s.replace(old,new,1)

# Replace the practical grid guide with search -> popular -> accordion -> direct navigation.
start=app.index('function InfoGuidePage() {')
end=app.index('\nfunction ',start+10)
new_guide=r'''function InfoGuidePage() {
  const [guideSearch,setGuideSearch]=useState("");
  const [openGuide,setOpenGuide]=useState("");
  const guides=[
    {key:"pets",icon:"🐾",title:"우리 아이",keywords:"등록 프로필 체중 성장 기록 앨범 사진 예방접종",steps:["우리 아이에서 강아지 또는 고양이를 등록해요.","프로필 사진과 생년월일·품종·현재 체중을 입력해요.","체중 기록과 성장앨범에 사진을 추가하면 성장 과정을 한곳에서 볼 수 있어요."],tip:"여러 마리를 등록했다면 아이 선택 메뉴에서 바로 전환할 수 있어요."},
    {key:"music",icon:"🎵",title:"Pet음악",keywords:"음악 재생 반복 좋아요 댓글 즐겨찾기 강아지 고양이",steps:["강아지·고양이 필터에서 원하는 음악을 찾아요.","곡을 눌러 재생하고 1곡 반복 또는 전체 반복을 선택할 수 있어요.","마음에 드는 곡은 좋아요하고 댓글로 반응을 남길 수 있어요."],tip:"좋아요한 음악은 회원정보에서 다시 확인할 수 있어요."},
    {key:"nearby",icon:"📍",title:"내 주변 Pet",keywords:"주소 검색 지도 병원 약국 펫샵 미용 호텔 후기 위치",steps:["주소 검색창에 찾고 싶은 지역을 입력해요.","주변 동물병원·동물약국·펫샵·미용·호텔 등을 지도와 목록에서 확인해요.","이용한 장소는 별점과 후기를 남길 수 있어요."],tip:"위치 권한을 허용하면 현재 위치 기준 거리도 확인할 수 있어요."},
    {key:"community",icon:"💬",title:"Pet톡",keywords:"커뮤니티 글쓰기 댓글 좋아요 내활동 신고",steps:["카테고리에서 관심 있는 글을 찾아 읽어요.","글쓰기에서 제목과 내용을 입력해 게시할 수 있어요.","댓글·좋아요를 이용하고 회원정보의 내 활동에서 다시 확인해요."],tip:"개인정보나 타인의 권리를 침해하는 내용은 게시하지 말아 주세요."},
    {key:"saju",icon:"🔮",title:"Pet사주",keywords:"사주 운세 궁합 보호자 오늘 펫운세",steps:["등록한 우리 아이를 선택해요.","기본 Pet사주·오늘의 펫운세·보호자 궁합 중 원하는 기능을 선택해요.","결과를 재미와 참고용으로 확인해요."],tip:"Pet사주 결과는 의학적 진단이나 실제 미래를 판단하는 자료가 아니에요."},
    {key:"tarot",icon:"🃏",title:"Pet타로",keywords:"타로 오늘의 Pet타로 궁합 마음 산책 활동 조언 저장 카드 22장",steps:["Pet타로에서 우리 아이와 원하는 주제를 선택해요.","메이저 아르카나 22장 중 마음이 가는 카드 한 장을 골라요.","결과와 해석을 확인하고 필요하면 회원정보에 저장해요."],tip:"오늘의 Pet타로·보호자 궁합·마음·산책·조언은 주제별로 하루 1회 뽑을 수 있어요."},
    {key:"petbti",icon:"🧠",title:"PetBTI",keywords:"성향 검사 질문 mbti 결과",steps:["검사할 우리 아이를 선택해요.","20개 질문에 평소 행동을 기준으로 답해요.","완료하면 우리 아이의 PetBTI 성향 결과를 확인할 수 있어요."],tip:"PetBTI는 재미와 이해를 돕기 위한 콘텐츠이며 전문 행동진단이 아니에요."},
    {key:"tips",icon:"💡",title:"Pet정보",keywords:"건강 식단 훈련 생활 정보 검색",steps:["카테고리 또는 검색창에서 궁금한 주제를 찾아요.","질문을 누르면 답변과 핵심 정보를 확인할 수 있어요.","필요한 내용은 반려생활 참고자료로 활용해요."],tip:"건강 이상이나 응급 증상은 정보글보다 동물병원 진료를 우선해 주세요."},
    {key:"news",icon:"📰",title:"Pet뉴스",keywords:"뉴스 기사 이미지 요약 원문 정책 건강",steps:["대표이미지가 확인된 최신 반려동물 뉴스를 살펴봐요.","기사 카드를 누르면 PetGrow 안에서 요약과 핵심 포인트를 먼저 읽을 수 있어요.","더 자세한 내용이 필요하면 원문 전체보기를 눌러 언론사 기사를 확인해요."],tip:"PetGrow는 기사 전문을 복사하지 않고 제공된 기사 설명을 바탕으로 핵심을 정리해 보여줘요."},
    {key:"my",icon:"👤",title:"회원정보",keywords:"회원정보 닉네임 기록 저장 좋아요 탈퇴 로그아웃",steps:["회원정보에서 닉네임과 계정 정보를 확인해요.","Pet톡 활동·좋아요한 콘텐츠·저장한 Pet사주·Pet타로 기록을 확인해요.","로그아웃이나 회원탈퇴도 회원정보에서 이용할 수 있어요."],tip:"회원탈퇴 전 필요한 기록이 있는지 먼저 확인해 주세요."},
    {key:"support",icon:"📢",title:"고객지원",keywords:"공지 문의 피드백 오류 광고 제휴",steps:["공지사항에서 서비스 변경이나 안내를 확인해요.","궁금한 점이나 오류는 문의·피드백으로 남겨요.","광고·제휴 관련 문의는 광고문의 메뉴를 이용해요."],tip:"오류 문의에는 문제가 발생한 메뉴와 상황을 함께 적으면 확인이 빨라져요."}
  ];
  const popular=["pets","tarot","music","news","nearby","my"];
  const q=guideSearch.trim().toLowerCase();
  const filtered=guides.filter(g=>!q||`${g.title} ${g.keywords} ${g.steps.join(" ")} ${g.tip}`.toLowerCase().includes(q));
  const go=(key)=>window.dispatchEvent(new CustomEvent("petgrow:navigate",{detail:key}));
  return <div className="legal-page-shell info-guide-v4">
    <section className="bg-card info-guide-search-card"><h2>무엇이 궁금하세요?</h2><p className="bg-sub">메뉴 이름이나 하고 싶은 일을 검색해 보세요.</p><div className="info-guide-search-row"><span>🔎</span><input className="bg-input" value={guideSearch} onChange={e=>setGuideSearch(e.target.value)} placeholder="예: 타로 저장, 음악 반복재생, 주소 검색"/>{guideSearch&&<button type="button" className="bg-chip" onClick={()=>setGuideSearch("")}>초기화</button>}</div></section>
    {!q&&<section className="info-guide-popular"><div className="info-guide-section-head"><h3>자주 찾는 이용방법</h3><small>바로 필요한 가이드부터 확인해요.</small></div><div className="info-guide-popular-grid">{popular.map(k=>{const g=guides.find(x=>x.key===k);return <button type="button" className="bg-card info-guide-popular-btn" key={k} onClick={()=>setOpenGuide(k)}><span>{g.icon}</span><b>{g.title}</b><small>{g.steps[0]}</small></button>})}</div></section>}
    <section className="info-guide-all"><div className="info-guide-section-head"><h3>{q?`검색 결과 ${filtered.length}개`:"메뉴별 이용가이드"}</h3><small>필요한 메뉴만 펼쳐서 볼 수 있어요.</small></div><div className="info-guide-accordion-list">{filtered.length?filtered.map(g=>{const open=openGuide===g.key;return <article className={"bg-card info-guide-accordion "+(open?"open":"")} key={g.key}><button type="button" className="info-guide-accordion-head" onClick={()=>setOpenGuide(open?"":g.key)}><span>{g.icon}</span><div><b>{g.title}</b><small>{g.steps[0]}</small></div><em>{open?"−":"＋"}</em></button>{open&&<div className="info-guide-accordion-body"><ol>{g.steps.map((s,i)=><li key={i}><span>{i+1}</span><p>{s}</p></li>)}</ol><div className="info-guide-tip">💡 {g.tip}</div><button type="button" className="bg-btn info-guide-go" onClick={()=>go(g.key)}>{g.title} 바로 이용하기 →</button></div>}</article>}):<div className="bg-card info-guide-empty">검색 결과가 없어요. 다른 단어로 검색해 보세요.</div>}</div></section>
  </div>;
}'''
app=app[:start]+new_guide+app[end:]

# PetNews: derive a faithful summary from the publisher-provided description only.
needle='''  if(selectedNews){const n=selectedNews;return <div className="legal-page-shell petnews-detail">'''
replacement='''  if(selectedNews){const n=selectedNews;const rawSummary=clean(n.description||"");const sentences=rawSummary.split(/(?<=[.!?。])\\s+|[·•]/).map(x=>clean(x)).filter(x=>x.length>10);const summaryLines=(sentences.length?sentences:[rawSummary]).filter(Boolean).slice(0,4);const corePoints=(sentences.length>1?sentences:rawSummary.split(/[,;]\\s*/).map(x=>clean(x)).filter(x=>x.length>12)).slice(0,3);const categoryWhy={"건강":"반려동물의 건강관리와 진료 판단에 참고할 만한 소식이에요.","정책·제도":"반려생활에 적용되는 제도나 정책 변화를 확인할 수 있는 소식이에요.","입양·보호":"유기동물 보호와 입양 환경을 이해하는 데 도움이 되는 소식이에요.","산업·서비스":"새로운 반려동물 제품·서비스와 시장 흐름을 살펴볼 수 있는 소식이에요.","반려견":"반려견 보호자가 알아두면 좋은 최근 소식이에요.","반려묘":"반려묘 보호자가 알아두면 좋은 최근 소식이에요.","반려동물":"반려생활과 관련된 최근 흐름을 확인할 수 있는 소식이에요."};return <div className="legal-page-shell petnews-detail">'''
rep(app,needle,replacement,'news detail summary vars')

old='<div className="petnews-detail-summary">{n.description||"기사의 핵심 내용은 원문에서 확인할 수 있어요."}</div><div className="petnews-source-note">PetGrow에서는 기사 제목과 제공된 요약을 보기 좋게 정리해 보여드려요. 기사 전문과 이미지의 권리는 각 언론사에 있으며, 자세한 내용은 원문에서 확인할 수 있어요.</div>'
new='<section className="petnews-pg-summary"><div className="petnews-summary-label">PETGROW 요약</div>{summaryLines.length?summaryLines.map((line,i)=><p key={i}>{line}</p>):<p>제공된 기사 설명이 짧아 자세한 내용은 원문에서 확인해 주세요.</p>}</section>{corePoints.length>0&&<section className="petnews-core-points"><h3>핵심 포인트</h3><ul>{corePoints.map((point,i)=><li key={i}><span>✓</span><p>{point}</p></li>)}</ul></section>}<section className="petnews-why"><b>반려인에게 왜 중요한가요?</b><p>{categoryWhy[n.category]||categoryWhy["반려동물"]}</p></section><div className="petnews-source-note">이 요약은 언론사가 제공한 제목·기사 설명 범위에서 PetGrow가 읽기 쉽게 정리한 내용이에요. 기사 전문과 이미지의 권리는 각 언론사에 있으며, 정확한 전체 내용은 원문에서 확인해 주세요.</div>'
rep(app,old,new,'news detail body')

css=r'''
/* PETGROW_GUIDE_NEWS_V4 */
.info-guide-v4{max-width:900px;margin:0 auto;padding:0 20px 60px}.info-guide-search-card{padding:22px!important;margin-bottom:20px}.info-guide-search-card h2{font-family:inherit!important;font-size:20px!important;font-weight:850!important;margin:0 0 5px!important}.info-guide-search-card>p{margin:0 0 14px}.info-guide-search-row{display:flex;align-items:center;gap:8px}.info-guide-search-row>span{font-size:20px}.info-guide-search-row .bg-input{flex:1}.info-guide-section-head{display:flex;align-items:flex-end;justify-content:space-between;gap:10px;margin:24px 2px 11px}.info-guide-section-head h3{font-family:inherit!important;font-size:16px!important;font-weight:850!important}.info-guide-section-head small{font-size:11px;color:var(--sub)}.info-guide-popular-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.info-guide-popular-btn{text-align:left;padding:16px!important;cursor:pointer}.info-guide-popular-btn>span{font-size:25px;display:block;margin-bottom:7px}.info-guide-popular-btn>b,.info-guide-popular-btn>small{display:block}.info-guide-popular-btn>b{font-size:14px}.info-guide-popular-btn>small{font-size:10.5px;color:var(--sub);line-height:1.5;margin-top:4px;word-break:keep-all}.info-guide-accordion-list{display:grid;gap:9px}.info-guide-accordion{padding:0!important;overflow:hidden;border-radius:18px!important}.info-guide-accordion-head{width:100%;border:0;background:#fff;padding:15px 16px;display:grid;grid-template-columns:34px minmax(0,1fr) 28px;gap:10px;align-items:center;text-align:left;cursor:pointer;color:var(--text)}.info-guide-accordion.open .info-guide-accordion-head{background:#f3f8f3}.info-guide-accordion-head>span{font-size:24px}.info-guide-accordion-head b,.info-guide-accordion-head small{display:block}.info-guide-accordion-head b{font-size:14px;font-weight:850}.info-guide-accordion-head small{font-size:10.5px;color:var(--sub);line-height:1.45;margin-top:3px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.info-guide-accordion-head em{font-style:normal;font-size:20px;color:var(--primary);text-align:center}.info-guide-accordion-body{padding:4px 18px 18px}.info-guide-accordion-body ol{list-style:none;padding:0;margin:8px 0 12px;display:grid;gap:9px}.info-guide-accordion-body li{display:flex;align-items:flex-start;gap:9px}.info-guide-accordion-body li>span{width:23px;height:23px;flex:0 0 23px;border-radius:50%;display:grid;place-items:center;background:#eaf4eb;color:var(--primary);font-size:11px;font-weight:900}.info-guide-accordion-body li p{font-size:12.5px;line-height:1.65;margin:1px 0 0;word-break:keep-all}.info-guide-tip{padding:11px 12px;border-radius:13px;background:#fffaf0;font-size:11.5px;line-height:1.65;color:#665d4d;word-break:keep-all}.info-guide-go{margin-top:13px;font-size:12px!important;padding:10px 16px!important;box-shadow:none!important}.info-guide-empty{text-align:center;padding:28px!important;color:var(--sub)}.petnews-pg-summary,.petnews-core-points,.petnews-why{margin-top:16px;border-radius:16px;padding:16px 17px}.petnews-pg-summary{background:#f4f8f4;border:1px solid #dfe9e0}.petnews-summary-label{font-size:10px;font-weight:900;letter-spacing:.12em;color:var(--primary);margin-bottom:8px}.petnews-pg-summary p{font-size:14px;line-height:1.8;margin:0 0 7px;word-break:keep-all}.petnews-pg-summary p:last-child{margin-bottom:0}.petnews-core-points{background:#fff;border:1px solid var(--border)}.petnews-core-points h3{font-family:inherit!important;font-size:14px!important;font-weight:850!important;margin:0 0 10px!important}.petnews-core-points ul{list-style:none;padding:0;margin:0;display:grid;gap:8px}.petnews-core-points li{display:flex;gap:8px;align-items:flex-start}.petnews-core-points li>span{color:var(--primary);font-weight:900}.petnews-core-points li p{font-size:12.5px;line-height:1.65;margin:0;word-break:keep-all}.petnews-why{background:#fff9ec}.petnews-why b{font-size:12px}.petnews-why p{font-size:12px;line-height:1.65;margin:5px 0 0;color:var(--sub);word-break:keep-all}@media(max-width:700px){.info-guide-v4{padding:0 14px 92px}.info-guide-search-card{padding:17px!important}.info-guide-search-row{align-items:stretch;flex-wrap:wrap}.info-guide-search-row>span{display:none}.info-guide-search-row .bg-input{flex:1 1 100%}.info-guide-popular-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.info-guide-section-head{align-items:flex-start;flex-direction:column;gap:2px}.petnews-pg-summary,.petnews-core-points,.petnews-why{padding:14px}.petnews-pg-summary p{font-size:13px}}
'''
rep(app,'.app-bottom-nav{position:fixed;',css+'\n.app-bottom-nav{position:fixed;','v4 css')

APP.write_text(app,encoding='utf-8')
print('PetGrow guide/news v4 applied')
